                        16));

                    if (g_removeSpace)
                        us.erase(std::remove(us.begin(), us.end(), L' '),
                                 us.end());

                    std::wstring ft = BuildFormattedText(fs, us, ts);

                    if (fmt & DT_CALCRECT) {
                        std::vector<wchar_t> b(ft.begin(), ft.end());
