                                                 (int)lines[i].length(), &lr,
                                                 dF | DT_CALCRECT, pDtp);
                                totalHeight +=
                                    (lr.bottom - lr.top) + g_lineSpacing;
                            } else {
                                RECT calcR = lr;
                                DrawTextExW_Orig(hdc, bl.data(),
                                                 (int)lines[i].length(), &calcR,
                                                 dF | DT_CALCRECT, pDtp);
                                DrawTextExW_Orig(hdc, bl.data(),
                                                 (int)lines[i].length(), &lr,
                                                 dF, pDtp);
                                totalHeight +=
                                    (calcR.bottom - calcR.top) + g_lineSpacing;
                            }
                        }
                        if (fmt & DT_CALCRECT) {
                            prc->bottom =
                                prc->top + totalHeight - g_lineSpacing;
                        }
                        ft_ret = totalHeight - g_lineSpacing;
                    } else {
                        ft_ret = DrawTextExW_Orig(
                            hdc, b.data(), (int)ft.length(), &r, dF, pDtp);
                    }

                    if (hOldFont) {
                        SelectObject(hdc, hOldFont);
                        DeleteObject(hNewFont);
                    }
                    return ft_ret;
                }
            }
        }
    }

    return DrawTextExW_Orig(hdc, psz, cch, prc, fmt, pDtp);
}

static BOOL CALLBACK RefreshExplorerCallback(HWND hwnd, LPARAM lParam) {
    DWORD dwProcessId;
    GetWindowThreadProcessId(hwnd, &dwProcessId);
    if (dwProcessId != GetCurrentProcessId()) {
        return TRUE;
    }

    wchar_t cls[MAX_PATH];
    if (GetClassNameW(hwnd, cls, MAX_PATH)) {
        if (wcscmp(cls, L"CabinetWClass") == 0) {
            PostMessage(hwnd, WM_COMMAND, 41504, 0);  // Refresh command
            InvalidateRect(hwnd, NULL, TRUE);
        } else if (wcscmp(cls, L"DirectUIHWND") == 0) {
            InvalidateRect(hwnd, NULL, TRUE);
        }
    }
    return TRUE;
}

void RefreshExplorer() {
    EnumWindows(RefreshExplorerCallback, 0);
}

BOOL Wh_ModInit() {
    GdiplusStartupInput gsi;
    GdiplusStartup(&g_gdiplusToken, &gsi, NULL);
    LoadSettings();
    HMODULE uxtheme = GetModuleHandle(L"uxtheme.dll");
    if (uxtheme) {
        GetThemeWindow_Ptr =
            (GetThemeWindow_t)GetProcAddress(uxtheme, "GetThemeWindow");
        GetThemeClassList_Ptr =
            (GetThemeClassList_t)GetProcAddress(uxtheme, "GetThemeClassList");

        Wh_SetFunctionHook((void*)GetProcAddress(uxtheme, "OpenThemeData"),
                           (void*)OpenThemeData_Hook,
                           (void**)&OpenThemeData_Orig);
        Wh_SetFunctionHook((void*)GetProcAddress(uxtheme, "OpenThemeDataEx"),
                           (void*)OpenThemeDataEx_Hook,
                           (void**)&OpenThemeDataEx_Orig);
        Wh_SetFunctionHook((void*)GetProcAddress(uxtheme, "CloseThemeData"),
                           (void*)CloseThemeData_Hook,
                           (void**)&CloseThemeData_Orig);

        Wh_SetFunctionHook(
            (void*)GetProcAddress(uxtheme, "DrawThemeBackground"),
            (void*)HookedDrawThemeBackground,
            (void**)&DrawThemeBackground_Orig);
    }

    if (uxtheme) {
        void* pOpenDpi = (void*)GetProcAddress(uxtheme, "OpenThemeDataForDpi");
        if (pOpenDpi) {
            Wh_SetFunctionHook(pOpenDpi, (void*)OpenThemeDataForDpi_Hook,
                               (void**)&OpenThemeDataForDpi_Orig);
        }
    }

    HMODULE user32 = GetModuleHandle(L"user32.dll");
    if (user32) {
        Wh_SetFunctionHook((void*)GetProcAddress(user32, "DrawTextW"),
                           (void*)DrawTextW_Hook, (void**)&DrawTextW_Orig);
        Wh_SetFunctionHook((void*)GetProcAddress(user32, "DrawTextExW"),
                           (void*)DrawTextExW_Hook, (void**)&DrawTextExW_Orig);
    }
    RefreshExplorer();
    return TRUE;
}

void Wh_ModUninit() {
    GdiplusShutdown(g_gdiplusToken);
    RefreshExplorer();
}
void Wh_ModSettingsChanged() {
    LoadSettings();
    RefreshExplorer();
}

// ==WindhawkMod==
// @id              explorer-font-changer-fork
// @name            Explorer Font Changer - Fork
// @description     Comic Sans anybody? Change your GDI fonts at will! Also, gloooowy!
// @version         0.3
// @author          Gabriela Cristei
// @github          https://github.com/cristeigabriela
// @include         explorer.exe
// @compilerOptions -luxtheme -lgdi32
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Explorer Font Changer

![Preview](https://raw.githubusercontent.com/cristeigabriela/images/refs/heads/main/windhawk-explorer-font-changer-0.2.png)

Change your Explorer GDI fonts at any time! Also, make text glow if you wish! Configurable at any time!

## Configuration:

- Font Face Name:
To not affect the Windows default-picked font face name, simply fill in the setting textbox with the value `None`.

- Glow text:
This toggles on the "Glow text" functionality, proxying calls to `user32!DrawTextW` and `user32!DrawTextExW` to `uxtheme.dll`'s "DrawGlowText" function. Thanks to the mod "Translucent Windows" for bringing this function to my attention!

- Glow: Red (0-255):
The red value of the glow text color (0-255).

- Glow: Green (0-255):
The green value of the glow text color (0-255).

- Glow: Blue (0-255):
The blue value of the glow text color (0-255).

- Glow: Alpha (0-255):
The alpha value of the glow text color (0-255).

- Glow: Intensity (1-..)
The intensity value of the glow that surrounds the text.

## System stability:

Explorer Font Changer is heavily tested against GDI handle leaks and there are none (known!) at the time of writing this.

This can be checked by others by going to System Informer, looking for `explorer.exe`, right-clicking the entry, going to "Miscellaneous", and then "GDI handles". Then, you can look at the font handles. Normally, you should see no handles present with your chosen font there!

## Glyph fallback:

If a string being drawn contains a character that your chosen font doesn't have a glyph for (e.g. an icon-font codepoint used by context menus, an accented letter, or an emoji), the mod detects this and leaves that particular draw call on the original, unmodified font instead of forcing your custom font and rendering "tofu" (`~` / boxes). This means icons in Explorer/Nilesoft Shell context menus, and text your font doesn't cover, keep rendering correctly.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
# Here you can define settings, in YAML format, that the mod users will be able
# to configure. Metadata values such as $name and $description are optional.
# Check out the documentation for more information:
# https://github.com/ramensoftware/windhawk/wiki/Creating-a-new-mod#settings
- font:
  - name: "None"
    $name: "Font Face Name"
  - glow: false
    $name: "Glow text"
  - r: 255
    $name: "Glow: Red (0-255)"
  - g: 255
    $name: "Glow: Green (0-255)"
  - b: 255
    $name: "Glow: Blue (0-255)"
  - a: 255
    $name: "Glow: Alpha (0-255)"
  - intensity: 4
    $name: "Glow: Intensity (1-..)"
  $name: Custom font
  $description: This font will be used for all font creation in Windows.
*/
// ==/WindhawkModSettings==


#include <string>
#include <vector>
#include <windhawk_utils.h>
#include <uxtheme.h>

using namespace std::string_view_literals;
using namespace WindhawkUtils;

namespace util {
    StringSetting s_font_name;
    bool s_glow = false;
    int s_glow_r = 255;
    int s_glow_g = 255;
    int s_glow_b = 255;
    int s_glow_a = 255;
    int s_glow_intensity = 0;

    // Class to declare transparent RAII types.
    template <class T, auto Fn>
    class raii {
    public:
        raii() = delete;
        raii(T handle) : m_handle(handle) {}
        ~raii() {
            Fn(m_handle);
        }

        // we don't need operator= or raii(raii&&) yet...

        auto& get() {
            return m_handle;
        }
        
        auto get() const {
            return m_handle;
        }

    private:
        T m_handle;
    };

    // RAII `HFONT`.
    using unique_hfont_t = raii<HFONT, DeleteObject>;

    // Alters search path to look in `System32` folder.
    HMODULE load_os_library(
        LPCWSTR library
    ) {
        return LoadLibraryExW(
            library,
            nullptr,
            LOAD_LIBRARY_SEARCH_SYSTEM32
        );
    }

    // Loosely reversed, initially referenced from Translucent Windows font, thanks!
    using draw_text_with_glow_t = HRESULT(WINAPI*)(
        HDC target_hdc,
        LPCWSTR text,
        UINT text_len,
        const RECT* rect,
        DWORD flags,
        COLORREF text_color,
        COLORREF glow_color,
        UINT glow_intensity,
        UINT unk1,
        BOOL unk2,
        // This one is useful in the scenario of painting within a hook,
        // as letting it fall back on, for example, `DrawTextW`, while
        // using this inside said function, would cause recursion.
        DTT_CALLBACK_PROC fallback_draw_text,
        LPARAM lparam
    );

    // Function is not exported by name, but it is found in the resource table.
    auto draw_text_with_glow_fn = reinterpret_cast<draw_text_with_glow_t>(
        GetProcAddress(
            load_os_library(L"uxtheme.dll"),
            MAKEINTRESOURCEA(126)
        )
    );

    // credit: "Translucent Windows" mod
    auto draw_text_with_glow(
        HDC target_hdc,
        const RECT* target_rect,
        const std::wstring_view text,
        DWORD format,
        COLORREF text_color,
        COLORREF glow_color,
        UINT glow_intensity,
        DTT_CALLBACK_PROC callback = nullptr,
        LPARAM lparam = 0
    ) {
        auto hr = S_FALSE;

        auto blend_fun = BLENDFUNCTION { AC_SRC_OVER, 0, 255, AC_SRC_ALPHA };
        auto bp_params = BP_PAINTPARAMS {
            .cbSize = sizeof(BP_PAINTPARAMS),
            .dwFlags = BPPF_ERASE,
            .prcExclude = nullptr,
            .pBlendFunction = &blend_fun
        };

        HDC buf_hdc = nullptr;
        auto buf_ptr = BeginBufferedPaint(
            target_hdc, target_rect, BPBF_TOPDOWNDIB, &bp_params, &buf_hdc);
        if (buf_ptr && buf_hdc) {
            SelectObject(buf_hdc, GetCurrentObject(target_hdc, OBJ_FONT));
            SetBkMode(buf_hdc, GetBkMode(target_hdc));
            SetBkColor(buf_hdc, GetBkColor(target_hdc));
            SetTextAlign(buf_hdc, GetTextAlign(target_hdc));
            SetTextCharacterExtra(buf_hdc, GetTextCharacterExtra(target_hdc));

            hr = draw_text_with_glow_fn(
                buf_hdc, text.data(), text.size(),
                target_rect, format, text_color, glow_color, glow_intensity,
                100, 100, callback, lparam
            );

            EndBufferedPaint(buf_ptr, TRUE);
        }

        return hr;
    }

    void change_font_in_struct(
        LOGFONTW* font
    ) {
        auto font_name = std::wstring_view(s_font_name.get());

        // Check font configuration.
        if (font_name != L"None"sv) {
            if (font_name.size() <= 31) {
                // `face_name` points to a total of 32 WORDs.
                auto face_name = static_cast<WCHAR*>(font->lfFaceName);

                std::memset(face_name, 0, ARRAYSIZE(font->lfFaceName));
                std::memcpy(
                    face_name, font_name.data(),
                    font_name.size() * sizeof(decltype(font_name)::value_type)
                );
            } else {
                Wh_Log(L"Trying to change font to \"%s\": size too long (%d)", font_name.data(), font_name.size());
            }
        }
    }

    // Checks whether every character in `text` has a real glyph in the font
    // described by `candidate_font`, when rendered on `hdc`. Used to avoid
    // swapping in a font that would render icon-font glyphs (e.g. Segoe MDL2
    // Assets / Segoe Fluent Icons private-use-area codepoints used by
    // context menus) or unsupported unicode characters as tofu ("~"/boxes).
    bool font_supports_text(
        HDC hdc,
        const LOGFONTW& candidate_font,
        const std::wstring_view text
    ) {
        if (text.empty()) {
            return true;
        }

        HFONT h_candidate = CreateFontIndirectW(&candidate_font);
        if (!h_candidate) {
            // Can't even create it, don't risk swapping.
            return false;
        }

        HFONT h_old = static_cast<HFONT>(SelectObject(hdc, h_candidate));

        std::vector<WORD> indices(text.size());
        DWORD result = GetGlyphIndicesW(
            hdc,
            text.data(),
            static_cast<int>(text.size()),
            indices.data(),
            GGI_MARK_NONEXISTING_GLYPHS
        );

        // Restore the HDC's prior font before we tear down the candidate.
        SelectObject(hdc, h_old);
        DeleteObject(h_candidate);

        if (result == GDI_ERROR) {
            // Couldn't verify (e.g. font/driver doesn't support the query),
            // be conservative and don't swap the font for this draw call.
            return false;
        }

        for (auto index : indices) {
            if (index == 0xFFFF) {
                // Missing glyph found - this font can't render this text.
                return false;
            }
        }

        return true;
    }

    std::pair<unique_hfont_t, LOGFONTW> hdc_update_font(
        HDC hdc,
        std::wstring_view text = {}
    ) {
        // Get current selected font.
        auto h_font = GetCurrentObject(hdc, OBJ_FONT);

        // Create struct for font.
        auto font = LOGFONTW { 0 };

        // Get `LOGFONTW` from font handle.
        GetObjectW(
            static_cast<HANDLE>(h_font),
            sizeof(font),
            static_cast<LPVOID>(&font)
        );

        // Keep an unmodified copy, in case we need to fall back to it.
        auto original_font = font;

        // Change font to the font specified in settings.
        change_font_in_struct(&font);

        // If the face actually changed and we have text to check, make sure
        // the new font can actually render it before committing to it. This
        // keeps icon-font glyphs (context menus, etc.) and characters your
        // custom font doesn't define from turning into tofu/"~".
        if (!text.empty() &&
            wcscmp(font.lfFaceName, original_font.lfFaceName) != 0) {
            if (!font_supports_text(hdc, font, text)) {
                font = original_font;
            }
        }

        // Create new font.
        auto h_new_font = CreateFontIndirectW(&font);

        // Select font.
        SelectObject(hdc, h_new_font);

        return { h_new_font, font };
    }

    void update_settings() {
        s_font_name      = StringSetting::make(L"font.name");
        s_glow           = Wh_GetIntSetting(L"font.glow") == 1;
        s_glow_r         = Wh_GetIntSetting(L"font.r");
        s_glow_g         = Wh_GetIntSetting(L"font.g");
        s_glow_b         = Wh_GetIntSetting(L"font.b");
        s_glow_a         = Wh_GetIntSetting(L"font.a");
        s_glow_intensity = Wh_GetIntSetting(L"font.intensity");
    }

    bool is_glow_enabled() {
        return s_glow;
    }

    COLORREF get_glow_abgr() {
        // 1. Get the colors
        auto r = static_cast<uint8_t>(
            s_glow_r & 0xff
        );

        auto g = static_cast<uint8_t>(
            s_glow_g & 0xff
        );
        
        auto b = static_cast<uint8_t>(
            s_glow_b & 0xff
        );

        auto a = static_cast<uint8_t>(
            s_glow_a & 0xff
        );

        // 2. Generate ABGR
        auto result = static_cast<COLORREF>(
            (a << 24) | (b << 16) | (g << 8) | r
        );

        return result;
    }

    int get_glow_intensity() {
        return s_glow_intensity;
    }
}

using draw_textw_hook_t = decltype(&DrawTextW);
static draw_textw_hook_t draw_textw_original = nullptr;

using draw_text_exw_hook_t = decltype(&DrawTextExW);
static draw_text_exw_hook_t draw_text_exw_original = nullptr;

// NOTE(gabriela): intentionally used for `DrawTextExW` as well, as the glow DrawText
// equivalent expects this to be a call to `DrawTextW`. 
INT WINAPI dtt_callback(
    HDC hdc,
    LPWSTR lpchText,
    INT cchText,
    LPRECT lprc,
    UINT format,
    LPARAM lParam
) {
    return draw_textw_original(hdc, lpchText, cchText, lprc, format);
}

INT WINAPI draw_textw_hook(
    HDC hdc,
    LPCWSTR lpchText,
    INT cchText,
    LPRECT lprc,
    UINT format
) {
    auto text_len = cchText >= 0
        ? static_cast<size_t>(cchText)
        : wcslen(lpchText);
    auto text = std::wstring_view{ lpchText, text_len };

    // Update font on HDC to settings font, from current HFONT.
    // Only actually swaps if the target font can render `text`.
    auto [h_new_font, _] = util::hdc_update_font(hdc, text);

    if (format & DT_CALCRECT) {
        return draw_textw_original(hdc, lpchText, cchText, lprc, format);;
    }

    if (util::is_glow_enabled()) {
        auto hr = util::draw_text_with_glow(
            hdc, lprc, text, format,
            GetTextColor(hdc), util::get_glow_abgr(), util::get_glow_intensity(),
            dtt_callback
        );

        if (SUCCEEDED(hr)) {
            // Call with DT_CALCRECT to get height of text in logical units.
            return draw_textw_original(hdc, lpchText, cchText, lprc, format | DT_CALCRECT);
        }
    }

    return draw_textw_original(hdc, lpchText, cchText, lprc, format);
}

INT WINAPI draw_text_exw_hook(
    HDC hdc,
    LPWSTR lpchText,
    INT cchText,
    LPRECT lprc,
    UINT format,
    LPDRAWTEXTPARAMS lpdtp
) {
    auto text_len = cchText >= 0
        ? static_cast<size_t>(cchText)
        : wcslen(lpchText);
    auto text = std::wstring_view{ lpchText, text_len };

    // Update font on HDC to settings font, from current HFONT.
    // Only actually swaps if the target font can render `text`.
    auto [h_new_font, _] = util::hdc_update_font(hdc, text);

    if (format & DT_CALCRECT) {
        return draw_text_exw_original(hdc, lpchText, cchText, lprc, format, lpdtp);
    }

    if (util::is_glow_enabled()) {
        auto hr = util::draw_text_with_glow(
            hdc, lprc, text, format,
            GetTextColor(hdc), util::get_glow_abgr(), util::get_glow_intensity(),
            dtt_callback
        );

        if (SUCCEEDED(hr)) {
            // Call with DT_CALCRECT to get height of text in logical units.
            return draw_text_exw_original(hdc, lpchText, cchText, lprc, format | DT_CALCRECT, lpdtp);
        }
    }

    return draw_text_exw_original(hdc, lpchText, cchText, lprc, format, lpdtp);
}

using get_text_extent_point32w_hook_t = decltype(&GetTextExtentPoint32W);
static get_text_extent_point32w_hook_t get_text_extent_point32w_original = nullptr;

BOOL WINAPI get_text_extent_point32w_hook(
    HDC hdc, LPCWSTR str, int c, LPSIZE size
) {
    auto text = std::wstring_view{ str, static_cast<size_t>(c) };
    auto [font, _] = util::hdc_update_font(hdc, text);
    return get_text_extent_point32w_original(hdc, str, c, size);
}

BOOL Wh_ModInit() {
    auto gdi32 = util::load_os_library(L"gdi32.dll");

    auto get_text_extent_point32w = reinterpret_cast<get_text_extent_point32w_hook_t>(
    GetProcAddress(gdi32, "GetTextExtentPoint32W")
    );
    Wh_SetFunctionHook(
    reinterpret_cast<void*>(get_text_extent_point32w),
    reinterpret_cast<void*>(get_text_extent_point32w_hook),
    reinterpret_cast<void**>(&get_text_extent_point32w_original)
    );

    // Get settings before applying hooks.
    util::update_settings();

    auto user32 = util::load_os_library(L"user32.dll");
    
    auto draw_textw = reinterpret_cast<draw_textw_hook_t>(
        GetProcAddress(user32, "DrawTextW")
    );
    Wh_SetFunctionHook(
        reinterpret_cast<void*>(draw_textw),
        reinterpret_cast<void*>(draw_textw_hook),
        reinterpret_cast<void**>(&draw_textw_original)
    );

    auto draw_text_exw = reinterpret_cast<draw_text_exw_hook_t>(
        GetProcAddress(user32, "DrawTextExW")
    );
    Wh_SetFunctionHook(
        reinterpret_cast<void*>(draw_text_exw),
        reinterpret_cast<void*>(draw_text_exw_hook),
        reinterpret_cast<void**>(&draw_text_exw_original)
    );

    return TRUE;
}

void Wh_ModSettingsChanged() {
    util::update_settings();
}

void Wh_ModUninit() {
    Wh_Log(L"Uninit");
}
